from pathlib import Path
import json,hashlib,html
from PIL import Image,ImageOps,ImageDraw,ImageFont
R=Path(__file__).resolve().parent;P=R.parent
def save(n,x):(R/n).write_text(json.dumps(x,indent=2,ensure_ascii=False),encoding='utf-8')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
e=lambda x:html.escape(str(x))
obs=json.loads((R/'OBSERVATIONS.json').read_text());sources=json.loads((R/'IMAGE-SOURCES.json').read_text())
for n,h in json.loads((R/'OBSERVATION-FREEZE.json').read_text())['sha256'].items():assert sha(R/n)==h
