sheet=Image.new('RGB',(1500,1500),'#f6f2e8');d=ImageDraw.Draw(sheet)
try:font=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',28)
except OSError:font=ImageFont.load_default()
for i,(p,b) in enumerate(boxes.items()):
 x=(i%3)*500;y=(i//3)*750;im=Image.open(R/'images'/f'{p}.jpg').crop(b).convert('RGB');im.thumbnail((474,680));sheet.paste(im,(x+(500-im.width)//2,y+48));d.text((x+15,y+8),p+(' (sensitivity)' if p=='f24v' else ''),fill='#173c38',font=font)
sheet.save(R/'plant-comparison.jpg',quality=94)
body='<h1>daro- pages · images before names</h1><p><b>No convincing fennel candidate emerged from these five herbal pages.</b> The strongest apparent feathery silhouette, f19v, resolves into broad toothed blades. This is a descriptive image result, not a rejection of a historical star–herb tradition or proof that no fennel drawing exists elsewhere.</p><p>All five pages with initial daro in available readings were selected before image inspection. f24v is displayed separately because its disputed C doar is not a daro hit. f57v is a diagram and was excluded. Morphological notes were frozen before reference and proposal lookup; the fennel hypothesis was already known, so this is not blinded or independent botanical annotation.</p><img src="plant-comparison.jpg" alt="Five daro pages plus separate f24v sensitivity, with folio IDs"><p>Contact-sheet crops preserve the depicted plant organs; click individual overviews below for page context. Original Yale scans and crop coordinates are retained.</p>'
body+='<h2>Reference and limits</h2><p>Fennel’s reference morphology combines repeated fine leaf division into threadlike terminal segments, sheathing bases and compound umbels of small yellow flowers. No selected drawing clearly shows that combination. Architecture and leaf division carry the comparison; blue versus yellow alone does not decide it. Modern botanical morphology cannot supply a strict exclusion rule for stylized medieval drawings. Dill also shares fine foliage and umbels, so even a positive match would need further discrimination.</p><p><a href="'+kew+'">Kew / Flora Zambesiaca and Flora of Tropical East Africa: fennel</a> · <a href="https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:837530-1/general-information">Kew: dill</a></p><p>No suitable medieval fennel depiction was visually inspected. The Hartlieb1462 lookup was inaccessible and is not visual evidence here. No scent, scale, fruit anatomy or living growth habit can be recovered from these drawings.</p>'
body+='<h2>Summary</h2><table><tr><th>Page</th><th>Visible evidence</th><th>Fennel assessment</th></tr>'
for o in obs:body+='<tr><td>'+e(o['page'])+'</td><td>'+e(o['leaves'])+'</td><td>'+e(judgments[o['page']]['fennel'])+'</td></tr>'
body+='</table>'
for o in obs:
 p=o['page'];ss=next(x for x in sources if x['page']==p)
 body+='<section><h2>'+p+(' · separate sensitivity' if p=='f24v' else '')+'</h2><a href="'+p+'-overview.jpg"><img class="page" src="'+p+'-overview.jpg" alt="Yale '+p+' whole page"></a><p><a href="'+ss['url']+'">Yale full-resolution source</a> · <a href="images/'+p+'.jpg">Local original</a></p>'
 body+='<h3>Image observations saved before reference lookup</h3>'
 for k in ['habit','leaves','flowers','root','uncertainty']:body+='<p><b>'+k.capitalize()+':</b> '+e(o[k])+'</p>'
 if p=='f19v':body+='<p><a href="f19v-upper.png">Native upper-leaf and flower detail</a> · <a href="f19v-lower-leaves.png">Native lower-leaf detail</a></p>'
 if p=='f43v':body+='<p><a href="f43v-right.png">Native right-hand drawing detail</a> · <a href="f43v-left.png">Left-hand crop</a> (left crop provided for access; whole-page view inspected)</p>'
 body+='<h3>Subsequent comparison</h3><p><b>'+e(judgments[p]['fennel'])+'</b>. '+e(judgments[p]['reason'])+'</p><p>'+e(judgments[p]['alternative_assessment'])+'</p>'
 body+='<h3>Other proposals remain visible</h3><p>These are competing suggestions, not validated identities. Source dates below may be aggregator dates rather than checked first attestations. Absence from this short list does not mean no other proposal exists.</p>'
 for z in proposals[p]:body+='<p><a href="'+z['source']+'">'+e(z['name'])+'</a> · '+e(z['by'])+' · '+e(z['date'])+'</p>'
 body+='<details><summary>Text readings · kept separate from image judgment</summary><p>'+locs[p]+'</p>'
 for z in alts[locs[p]]:body+='<p>'+e(z['reading']+': '+z['raw'])+'</p>'
 body+='</details></section>'
body+='<h2>What this does and does not establish</h2><p>No selected page is advanced to a fennel-based name or sound fit. The daro strings are paragraph words, not established plant captions. In particular f43v has two plants and no demonstrated ownership of darody. The four H pages are hand1; f43v is hand2. The similarity of daro strings to the f68r3 cluster reading doaro/doary has not established a lexical family.</p><p>This small selected set has no matched image controls or full-manuscript fennel search. It provides no prevalence or significance result and cannot reject a general astrology–herbal relationship. It found no convincing visual support for this particular proposed bridge under the retained readings.</p><h2>Records</h2>'
for n in ['PROTOCOL.json','PRE-IMAGE-FREEZE.json','OBSERVATIONS.json','OBSERVATION-FREEZE.json','COMPARISONS.json','ALTERNATIVE-PROPOSALS.json','READINGS.json','IMAGE-SOURCES.json','IMAGE-RECEIPTS.json','CROPS.json','CONTACT-CROPS.json','SOURCE-NOTES.json']:
 body+='<p><a href="'+n+'">'+n+'</a></p>'
(R/'report.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>daro plant image audit v91</title><style>body{font:17px system-ui;line-height:1.6;max-width:1100px;margin:40px auto;padding:0 20px;background:#f6f2e8;color:#173c38}img{max-width:100%;height:auto}img.page{max-height:850px;display:block;margin:auto}h1,h2,h3{line-height:1.2}section{border-top:2px solid #bed0c4;margin-top:2em;padding-top:1em}table{border-collapse:collapse}td,th{border:1px solid #abc;padding:8px;text-align:left}a{color:#126151}details{padding:10px;background:#e8eee5}</style>'+body+'</html>',encoding='utf-8')
save('STATUS.json',dict(primary_pages_inspected=5,primary_drawings_at_least=6,sensitivity_pages_inspected=1,observations_frozen_before_reference_lookup=True,independent_or_blinded=False,convincing_fennel_candidates=0,plant_identifications_established=0,word_to_plant_ownership_established=0,names_or_sounds_fitted=0,contact_sheet_visually_reviewed=True,html_appearance_reviewed=False))
